import React from 'react';
import { Order } from '../types';

interface OrderStatsProps {
  orders: Order[];
}

const OrderStats: React.FC<OrderStatsProps> = ({ orders }) => {
  const getStatusCounts = () => {
    const counts = {
      PENDING: 0,
      CONFIRMED: 0,
      PREPARING: 0,
      READY: 0,
      COMPLETED: 0,
      CANCELLED: 0,
    };

    const totalRevenue = orders
      .filter(order => order.status !== 'CANCELLED')
      .reduce((sum, order) => sum + order.totalAmount, 0);

    orders.forEach(order => {
      counts[order.status]++;
    });

    return { counts, totalRevenue };
  };

  const { counts, totalRevenue } = getStatusCounts();

  const stats = [
    {
      key: 'PENDING',
      label: 'Pending',
      icon: '⏳',
      bg: 'bg-yellow-50',
      border: 'border-yellow-200',
      text: 'text-yellow-800',
      count: counts.PENDING
    },
    {
      key: 'CONFIRMED',
      label: 'Confirmed',
      icon: '✓',
      bg: 'bg-blue-50',
      border: 'border-blue-200',
      text: 'text-blue-800',
      count: counts.CONFIRMED
    },
    {
      key: 'PREPARING',
      label: 'Preparing',
      icon: '👨‍🍳',
      bg: 'bg-orange-50',
      border: 'border-orange-200',
      text: 'text-orange-800',
      count: counts.PREPARING
    },
    {
      key: 'READY',
      label: 'Ready',
      icon: '🔔',
      bg: 'bg-green-50',
      border: 'border-green-200',
      text: 'text-green-800',
      count: counts.READY
    },
    {
      key: 'COMPLETED',
      label: 'Completed',
      icon: '✅',
      bg: 'bg-gray-50',
      border: 'border-gray-200',
      text: 'text-gray-800',
      count: counts.COMPLETED
    },
    {
      key: 'CANCELLED',
      label: 'Cancelled',
      icon: '❌',
      bg: 'bg-red-50',
      border: 'border-red-200',
      text: 'text-red-800',
      count: counts.CANCELLED
    }
  ];

  return (
    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-6">
      {stats.map(stat => (
        <div
          key={stat.key}
          className={`${stat.bg} ${stat.border} border rounded-xl p-4 transition-all duration-200 hover:shadow-md hover:scale-105 cursor-pointer`}
        >
          <div className="flex items-center justify-between mb-2">
            <span className="text-2xl">{stat.icon}</span>
            {stat.count > 0 && (
              <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></div>
            )}
          </div>
          <div className={`text-2xl font-bold ${stat.text}`}>{stat.count}</div>
          <div className={`text-sm ${stat.text} opacity-75`}>{stat.label}</div>
        </div>
      ))}

      {/* Total Revenue Card */}
      <div className="bg-gradient-to-br from-purple-50 to-indigo-50 border border-purple-200 rounded-xl p-4 col-span-2 md:col-span-3 lg:col-span-6">
        <div className="flex items-center justify-between">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="text-2xl">💰</span>
              <span className="text-sm text-purple-600 font-medium">Total Revenue</span>
            </div>
            <div className="text-3xl font-bold text-purple-800">
              ${totalRevenue.toFixed(2)}
            </div>
            <div className="text-sm text-purple-600 opacity-75">
              From {orders.filter(o => o.status !== 'CANCELLED').length} orders
            </div>
          </div>
          <div className="text-4xl opacity-20">📊</div>
        </div>
      </div>
    </div>
  );
};

export default OrderStats;
